cat >> tests/tasks.test.ts <<'EOF'

describe("SL-004 reject empty and over-long titles", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  async function assertRejected(title: unknown, message: string): Promise<void> {
    const response = await createTask(server, title as string);
    assert.equal(response.status, 400);
    const body = (await response.json()) as { error: { code: string; message: string } };
    assert.equal(body.error.code, "validation_failed");
    assert.equal(body.error.message, message);
  }

  it("AC-1: an empty title is rejected with a reason and nothing is stored", async () => {
    await assertRejected("", "A title is required.");
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-1: a title of only spaces is rejected", async () => {
    await assertRejected("   \t ", "A title is required.");
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-1: a missing or non-string title is rejected", async () => {
    await assertRejected(undefined, "Title must be a string.");
    await assertRejected(42, "Title must be a string.");
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-2: a 501-character title is rejected and nothing is stored", async () => {
    await assertRejected("a".repeat(501), "The title is too long (maximum 500 characters).");
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-2: length is measured after trimming, so 500 characters plus spaces is accepted", async () => {
    const response = await createTask(server, `  ${"a".repeat(500)}  `);
    assert.equal(response.status, 201);
    const { task } = (await response.json()) as { task: Task };
    assert.equal(task.title.length, 500);
  });

  it("a request body that is not JSON is answered 400 invalid_json", async () => {
    const response = await fetch(`${server.baseUrl}/api/tasks`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: "{nope",
    });
    assert.equal(response.status, 400);
    const body = (await response.json()) as { error: { code: string } };
    assert.equal(body.error.code, "invalid_json");
  });

  it("AC-1: the page has a role=alert message element and shows the server's error message", async () => {
    const html = await (await fetch(`${server.baseUrl}/`)).text();
    const script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    assert.match(html, /<[^>]+id=["']form-message["'][^>]*role=["']alert["']/);
    assert.match(script, /form-message/);
    assert.match(script, /error\.message/);
    assert.doesNotMatch(script, /innerHTML/);
  });
});
EOF
